# -*- coding: utf-8 -*-
from lib import *
import lib
def struct():
    # 以赛亚书结构条：66 章 ~ 66 卷圣经（记忆钩，不是神学论证）
    segs = [(1, 12, "#f2c14e", "1–12 以马内利书"), (13, 23, "#ff6b5b", "13–23 列国神谕"), (24, 27, "#a98bff", "24–27 小启示录"), (28, 35, "#ff9f43", "28–35 六祸与锡安"),
            (36, 39, "#8c97b2", "36–39 历史插曲"), (40, 48, "#3ccf8e", "40–48 安慰·古列"), (49, 57, "#ff7eb6", "49–57 受苦的仆人"), (58, 66, "#2ed3c6", "58–66 新天新地")]
    W = 1200; o = [f'<svg viewBox="0 0 {W} 190" role="img" aria-label="以赛亚书结构条">']
    X = lambda c: 20 + (c - 1) / 66 * (W - 40)
    for i, (a, b, c, t) in enumerate(segs):
        x1, x2 = X(a), X(b + 1); y = 40 if i % 2 == 0 else 100
        o.append(f'<rect class="bar" style="animation-delay:{i*.08:.2f}s" x="{x1:.0f}" y="70" width="{x2-x1-3:.0f}" height="26" rx="6" fill="{c}"/>')
        o.append(f'<text x="{(x1+x2)/2:.0f}" y="{y if i%2==0 else 128}" text-anchor="middle" font-size="15" font-weight="700">{t}</text>')
    o.append(f'<line x1="{X(40):.0f}" y1="56" x2="{X(40):.0f}" y2="112" stroke="#fff" stroke-width="3" stroke-dasharray="5 4"/>')
    o.append(f'<text x="{X(20):.0f}" y="168" text-anchor="middle" font-size="16" font-weight="800" fill="#ff6b5b">⚖️ 1–39 审判为主（亚述时期）</text><text x="{X(53):.0f}" y="168" text-anchor="middle" font-size="16" font-weight="800" fill="#3ccf8e">🕊️ 40–66 安慰为主（展望被掳与归回）</text></svg>')
    return f'<div class="era reveal"><div class="in">{"".join(o)}</div></div>'
